/** Human-authored short learning guidance, not historical etymology or HSK-level evidence. */
export const DEEP_NOTES=Object.freeze({
'我':['Personal pronoun','我 identifies the speaker. In 我的, 的 links the speaker to something they possess.','Compare 我 (I/me) with 我们 (we/us).'],
'你':['Direct address','你 normally addresses one person. 你们 marks more than one person.','你好 is a greeting, not an exact translation of “you good”.'],
'好':['Meaning depends on context','好 describes something as good; 好吃 is specifically used for enjoyable taste.','Notice 好 in 你好 and in 好吃 has different functions.'],
'是':['Identity statements','是 connects a subject to a noun or identity: 我是学生。','Do not assume Chinese adjectives always need 是.'],
'人':['People and groups','人 can refer to a person and appears after place or group names.','中国人 refers to a Chinese person; 家人 is a family member.'],
'中':['Compounds matter','中国 and 中文 share 中, but each whole word has its own meaning.','Do not translate a compound by simply concatenating character glosses.'],
'文':['Written language','文 participates in words about language, writing and culture.','Compare 中文 (Chinese language) and 文化 (culture).'],
'学':['Education words','学生 is “student”; 学校 is “school.” Both contain 学.','A character meaning cue does not replace learning whole-word meanings.'],
'生':['Meaning across compounds','生日 means birthday while 学生 means student.','Look at how the same character contributes to different words.'],
'书':['Books and activities','书店 means bookstore. 看书 means to read books.','Notice the difference between an object-related noun and an activity.'],
'看':['Looking and reading','看书 means reading books; 看见 expresses seeing something.','The same character can serve different verbs and constructions.'],
'吃':['Verb-object phrases','吃饭 usually means eating a meal, not literally only eating cooked rice.','好吃 describes something as tasty.'],
'喝':['Drink with an object','喝水 and 喝茶 name different drinks after the verb 喝.','Practice recognizing the whole phrase in a sentence.'],
'水':['Word composition','水果 means fruit; it is not simply a compositional translation of water + fruit.','Keep the meaning of the full word distinct from the component.'],
'茶':['Beverage and container','茶 can name tea, while 茶杯 refers to a cup used for tea.','Listen for tone differences between complete example words.'],
'大':['Size and fixed vocabulary','大 describes size, but 大学 is the noun university.','Avoid overgeneralizing from the character’s literal gloss.'],
'小':['Size and age','小 means small, but 小学 is a primary school.','Treat the vocabulary form as an independent lexical item.'],
'天':['Time expressions','今天 means today and 明天 means tomorrow.','Review temporal expressions as complete words.'],
'日':['Dates and routines','生日 means birthday and 日记 means diary.','Characters may have useful clues without a fully predictable compound meaning.'],
'月':['Calendar and sky','一月 identifies January; 月亮 refers to the moon.','Compare number + 月 constructions with the word 月亮.'],
'说':['Speech vocabulary','说话 means speaking; 小说 refers to a novel.','The same character does not make all related words interchangeable.'],
'听':['Listening words','听歌 is listening to songs; 听见 is to hear.','Pay attention to activity versus successful perception.'],
'有':['Possession and existence','有 may communicate possession or existence depending on context.','没有 is commonly used for not having or nonexistence.'],
'不':['Negation and tones','不 often negates verbs and adjectives. Its spoken tone may change before another fourth tone.','Contrast dictionary bù with spoken bú in 不是.'],
'再':['Again or later','再 often refers to doing something again; 再见 is a fixed goodbye expression.','Learn the phrase rather than translating every part literally.'],
'家':['Home and family','家人 means family member, while 回家 describes going home.','Notice the difference between family relationships and movement.'],
});
export function guideFor(lesson){if(!lesson)return null;const [topic,explanation,comparison]=DEEP_NOTES[lesson.hanzi]||['Character in context',lesson.note,`Compare ${lesson.words[0].hanzi} (${lesson.words[0].english}) and ${lesson.words[1].hanzi} (${lesson.words[1].english}).`];return {topic,explanation,comparison};}
